style.css:
/* === Magister Dark Theme (for kandinsky.magister.net) === */
@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("kandinsky.magister.net") {
/* ===== BASE ===== */
  html, body {
    background: #121212 !important;
    color: #e0e0e0 !important;
  }

  /* ===== STRUCTURE ===== */
  header, nav, .topbar, .sidebar, .app-header {
    background: #1c1c1c !important;
    border-bottom: 1px solid #2a2a2a !important;
    color: #e0e0e0 !important;
  }

  main, .main, #main, .container, .content {
    background: #121212 !important;
    color: #e0e0e0 !important;
  }

  .card, .panel, .module, .widget, .tile, .lesson-card {
    background: #1e1e1e !important;
    border: 1px solid #333 !important;
    color: #e0e0e0 !important;
  }

  /* ===== TEXT ===== */
  a, .link, .nav-link, .btn-link {
    color: #81a1c1 !important;
  }
  a:hover, .link:hover {
    color: #8fbcbb !important;
  }

  h1, h2, h3, h4, h5, h6, p, span, label {
    color: #e0e0e0 !important;
  }

  /* ===== BUTTONS ===== */
  button, .btn {
    background: #2a2a2a !important;
    color: #e0e0e0 !important;
    border: 1px solid #444 !important;
    border-radius: 6px !important;
    transition: background 0.2s ease;
  }
  button:hover, .btn:hover {
    background: #3a3a3a !important;
  }

  /* ===== INPUTS ===== */
  input, select, textarea {
    background: #1a1a1a !important;
    color: #e0e0e0 !important;
    border: 1px solid #333 !important;
    border-radius: 4px !important;
  }
  input:focus, textarea:focus, select:focus {
    border-color: #81a1c1 !important;
    box-shadow: 0 0 3px #81a1c1 !important;
  }

  /* ===== TABLES ===== */
  table {
    background: #1a1a1a !important;
    color: #e0e0e0 !important;
    border-color: #333 !important;
  }
  th {
    background: #1e1e1e !important;
    color: #fff !important;
  }
  td {
    border-color: #333 !important;
  }
  tr:nth-child(even) {
    background: #181818 !important;
  }

  /* ===== SCROLLBARS ===== */
  * {
    scrollbar-width: thin;
    scrollbar-color: #444 #1a1a1a;
  }
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-track {
    background: #1a1a1a;
  }
  ::-webkit-scrollbar-thumb {
    background: #444;
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #555;
  }

  /* ===== NOTIFICATIONS ===== */
  .alert, .notification, .toast {
    background: #2b2b2b !important;
    border: 1px solid #444 !important;
    color: #e0e0e0 !important;
  }

  /* ===== SCHEDULE / AGENDA ===== */
  .rooster, .agenda, .calendar, .schedule {
    background: #121212 !important;
    color: #e0e0e0 !important;
  }

  .agenda-item, .lesson, .event {
    background: #1d1d1d !important;
    border: 1px solid #333 !important;
  }

  /* ===== MESSAGES / GRADES ===== */
  .message, .grade, .resultaat, .berichten {
    background: #1c1c1c !important;
    border-color: #333 !important;
    color: #e0e0e0 !important;
  }

  /* ===== LOGIN PAGE ===== */
  .login, .login-container {
    background: #121212 !important;
    color: #e0e0e0 !important;
  }

  /* ===== LOGO ===== */
  .logo img {
    filter: brightness(0) invert(1) !important;
  }
}
